"""Exhaustive check over all graphs on n <= NMAX vertices (generated by vertex augmentation,
deduplicated by pynauty canonical certificates; counts compared with OEIS A000088).

For each n records, over connected graphs:
  - max Int (Theorem 5: should be Int(P_n), equality iff P_n, or n=4 and C_4)
  - min noncol over graphs with no pendant vertex (delta >= 2)  [Problem 2 / 17(b)]
  - min noncol over 2-connected graphs of diameter >= 4          [Problem 17(a)]
and logs every graph with delta>=2 and noncol <= 2(n-4) to data/exhaustive_n<=NMAX.jsonl.
"""
import sys, json, itertools
from math import comb
import networkx as nx
import pynauty
from interval import distances, noncol

NMAX = int(sys.argv[1]) if len(sys.argv) > 1 else 9
A000088 = {1: 1, 2: 2, 3: 4, 4: 11, 5: 34, 6: 156, 7: 1044, 8: 12346, 9: 274668, 10: 12005168}


def cert(n, adj):
    g = pynauty.Graph(n, adjacency_dict={i: list(a) for i, a in enumerate(adj)})
    return pynauty.certificate(g)


def g6(n, adj):
    G = nx.Graph(); G.add_nodes_from(range(n))
    for u in range(n):
        for v in adj[u]:
            if u < v: G.add_edge(u, v)
    return nx.to_graph6_bytes(G, header=False).decode().strip()


level = {cert(1, [[]]): (1, [[]])}
out = open(f"data/exhaustive_n_le_{NMAX}.jsonl", "w")
summary = []
for n in range(1, NMAX + 1):
    if n > 1:
        new = {}
        for (m, adj) in level.values():
            for r in range(0, m + 1):
                for S in itertools.combinations(range(m), r):
                    a2 = [list(x) for x in adj] + [list(S)]
                    for s in S: a2[s].append(m)
                    c = cert(n, a2)
                    if c not in new:
                        new[c] = (n, a2)
        level = new
    assert len(level) == A000088[n], (n, len(level))
    PnInt = (n**3 - n) // 6
    maxInt, maxInt_g6 = -1, []
    min_d2, min_d2_list = None, []
    min_2c, min_2c_list = None, []
    ncon = nd2 = n2c = 0
    for (m, adj) in level.values():
        D = distances(n, adj)
        if (D < 0).any():
            continue
        ncon += 1
        nc = noncol(D)
        Int = comb(n, 2) + comb(n, 3) - nc
        code = g6(n, adj)
        if Int > maxInt: maxInt, maxInt_g6 = Int, [code]
        elif Int == maxInt: maxInt_g6.append(code)
        if n >= 3 and min(len(a) for a in adj) >= 2:
            nd2 += 1
            if min_d2 is None or nc < min_d2: min_d2, min_d2_list = nc, [code]
            elif nc == min_d2: min_d2_list.append(code)
            if n >= 8 and nc <= 2 * (n - 4):
                out.write(json.dumps({"n": n, "g6": code, "noncol": nc, "Int": Int, "diam": int(D.max()),
                                      "type": "delta>=2, noncol<=2(n-4)"}) + "\n")
            G = nx.from_graph6_bytes(code.encode())
            if n >= 3 and nx.is_biconnected(G) and D.max() >= 4:
                n2c += 1
                if min_2c is None or nc < min_2c: min_2c, min_2c_list = nc, [code]
                elif nc == min_2c: min_2c_list.append(code)
    rec = {"n": n, "graphs": len(level), "connected": ncon, "maxInt": maxInt, "Int(P_n)": PnInt,
           "maxInt_graphs": maxInt_g6, "delta>=2": nd2, "min_noncol_delta2": min_d2,
           "min_noncol_delta2_graphs": min_d2_list[:20], "n_min_delta2": len(min_d2_list),
           "2conn_diam>=4": n2c, "min_noncol_2conn_diam4": min_2c, "min_2c_graphs": min_2c_list[:20],
           "2(n-4)": 2 * (n - 4)}
    summary.append(rec)
    print(json.dumps(rec), flush=True)
out.close()
json.dump(summary, open(f"data/exhaustive_summary_n_le_{NMAX}.json", "w"), indent=1)
